{"version":3,"file":"main.jsdbx","sources":["../../../src/client/ach-transfer/components/AccountDropdown.tsx","../../../src/client/ach-transfer/app.tsx","../../../src/client/ach-transfer/main.tsx"],"sourcesContent":["import React, { useState, useRef, useEffect, useCallback } from "react";

interface Account {
  sys_id: string;
  number: string;
  account_type: string;
  balance: string;
  holder: string;
}

interface AccountDropdownProps {
  accounts: Account[];
  selectedAccount: Account | null;
  onSelect: (account: Account | null) => void;
  loading: boolean;
}

function formatBalance(balance: string): string {
  const num = parseFloat(balance);
  if (isNaN(num)) return balance;
  return num.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function accountLabel(acct: Account): string {
  return `${acct.number} — ${acct.holder} — ${acct.account_type} ($${formatBalance(acct.balance)})`;
}

export default function AccountDropdown({ accounts, selectedAccount, onSelect, loading }: AccountDropdownProps) {
  const [open, setOpen] = useState(false);
  const [filter, setFilter] = useState("");
  const [activeIndex, setActiveIndex] = useState(-1);
  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLUListElement>(null);

  const filtered = accounts.filter((a) => {
    if (!filter) return true;
    const q = filter.toLowerCase();
    return (
      a.number.toLowerCase().includes(q) ||
      a.account_type.toLowerCase().includes(q) ||
      a.holder.toLowerCase().includes(q) ||
      a.balance.includes(q)
    );
  });

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, []);

  useEffect(() => {
    setActiveIndex(-1);
  }, [filter]);

  useEffect(() => {
    if (activeIndex >= 0 && listRef.current) {
      const item = listRef.current.children[activeIndex] as HTMLElement;
      if (item) item.scrollIntoView({ block: "nearest" });
    }
  }, [activeIndex]);

  const openDropdown = useCallback(() => {
    setOpen(true);
    setFilter("");
    setActiveIndex(-1);
    setTimeout(() => inputRef.current?.focus(), 0);
  }, []);

  const selectAccount = useCallback((acct: Account) => {
    onSelect(acct);
    setOpen(false);
    setFilter("");
  }, [onSelect]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (!open) {
      if (e.key === "ArrowDown" || e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        openDropdown();
      }
      return;
    }

    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        setActiveIndex((prev) => (prev < filtered.length - 1 ? prev + 1 : 0));
        break;
      case "ArrowUp":
        e.preventDefault();
        setActiveIndex((prev) => (prev > 0 ? prev - 1 : filtered.length - 1));
        break;
      case "Enter":
        e.preventDefault();
        if (activeIndex >= 0 && activeIndex < filtered.length) {
          selectAccount(filtered[activeIndex]);
        }
        break;
      case "Escape":
        e.preventDefault();
        setOpen(false);
        break;
      case "Tab":
        setOpen(false);
        break;
    }
  };

  const listboxId = "account-listbox";
  const activeOptionId = activeIndex >= 0 ? `account-option-${activeIndex}` : undefined;

  return (
    <div ref={containerRef} style={{ position: "relative" }}>
      <label
        id="account-label"
        style={{
          display: "block",
          marginBottom: "4px",
          fontSize: "12px",
          fontWeight: 600,
          color: "#666",
          textTransform: "uppercase",
          letterSpacing: "0.5px",
        }}
      >
        Account *
      </label>

      {!open ? (
        <div
          role="combobox"
          aria-expanded={open}
          aria-haspopup="listbox"
          aria-controls={listboxId}
          aria-labelledby="account-label"
          tabIndex={0}
          onClick={openDropdown}
          onKeyDown={handleKeyDown}
          style={{
            width: "100%",
            padding: "8px 12px",
            border: "1px solid #ccc",
            borderRadius: "4px",
            background: "#fff",
            color: selectedAccount ? "#333" : "#999",
            fontSize: "14px",
            textAlign: "left",
            cursor: "pointer",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            minHeight: "36px",
            boxSizing: "border-box",
          }}
        >
          <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
            {loading ? "Loading accounts..." : selectedAccount ? accountLabel(selectedAccount) : "Select an account"}
          </span>
          <span aria-hidden="true" style={{ marginLeft: "8px", flexShrink: 0 }}>▾</span>
        </div>
      ) : (
        <div
          style={{
            width: "100%",
            border: "1px solid #ccc",
            borderRadius: "4px",
            background: "#fff",
            boxSizing: "border-box",
          }}
        >
          <input
            ref={inputRef}
            type="text"
            role="combobox"
            aria-expanded={true}
            aria-controls={listboxId}
            aria-autocomplete="list"
            aria-activedescendant={activeOptionId}
            aria-labelledby="account-label"
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Type to search by number, holder, or type..."
            style={{
              width: "100%",
              padding: "8px 12px",
              border: "none",
              borderBottom: "1px solid #eee",
              outline: "none",
              fontSize: "14px",
              color: "#333",
              background: "transparent",
              boxSizing: "border-box",
            }}
          />
          <ul
            ref={listRef}
            id={listboxId}
            role="listbox"
            aria-labelledby="account-label"
            style={{
              listStyle: "none",
              margin: 0,
              padding: 0,
              maxHeight: "240px",
              overflowY: "auto",
            }}
          >
            {filtered.length === 0 ? (
              <li
                role="presentation"
                style={{
                  padding: "12px",
                  color: "#999",
                  fontSize: "14px",
                  textAlign: "center",
                }}
              >
                {filter ? "No matching accounts" : "No accounts available"}
              </li>
            ) : (
              filtered.map((acct, idx) => (
                <li
                  key={acct.sys_id}
                  id={`account-option-${idx}`}
                  role="option"
                  aria-selected={selectedAccount?.sys_id === acct.sys_id}
                  onClick={() => selectAccount(acct)}
                  onMouseEnter={() => setActiveIndex(idx)}
                  style={{
                    padding: "8px 12px",
                    cursor: "pointer",
                    fontSize: "14px",
                    color: "#333",
                    background:
                      idx === activeIndex
                        ? "#f0f0f0"
                        : selectedAccount?.sys_id === acct.sys_id
                        ? "#e6f2ff"
                        : "transparent",
                    borderBottom: "1px solid #f5f5f5",
                  }}
                >
                  <div style={{ fontWeight: 600 }}>{acct.number}</div>
                  <div style={{ fontSize: "12px", color: "#666", marginTop: "2px" }}>
                    {acct.holder} — {acct.account_type} — ${formatBalance(acct.balance)}
                  </div>
                </li>
              ))
            )}
          </ul>
        </div>
      )}
    </div>
  );
}
","import React, { useState, useEffect } from "react";
import AccountDropdown from "./components/AccountDropdown";

interface TransactionResult {
  sys_id: string;
  account_number: string;
  amount: string;
  type: string;
  status: string;
  webhook_status: string | number;
}

interface Account {
  sys_id: string;
  number: string;
  account_type: string;
  balance: string;
  holder: string;
}

function getToken(): string {
  return (window as any).g_ck || "";
}

const cardStyle: React.CSSProperties = {
  background: "#fff",
  borderRadius: "8px",
  boxShadow: "0 1px 4px rgba(0,0,0,0.12)",
  marginBottom: "16px",
};

const labelStyle: React.CSSProperties = {
  display: "block",
  marginBottom: "4px",
  fontSize: "12px",
  fontWeight: 600,
  color: "#666",
  textTransform: "uppercase" as const,
  letterSpacing: "0.5px",
};

const inputStyle: React.CSSProperties = {
  width: "100%",
  padding: "8px 12px",
  fontSize: "14px",
  border: "1px solid #ccc",
  borderRadius: "4px",
  boxSizing: "border-box",
  color: "#333",
  backgroundColor: "#fff",
  outline: "none",
};

export default function App() {
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [selectedAccount, setSelectedAccount] = useState<Account | null>(null);
  const [accountsLoading, setAccountsLoading] = useState(true);
  const [amount, setAmount] = useState("");
  const [description, setDescription] = useState("");
  const [webhookKey, setWebhookKey] = useState("");
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [messageType, setMessageType] = useState<"success" | "error" | "">("");
  const [transaction, setTransaction] = useState<TransactionResult | null>(null);

  useEffect(() => {
    const fetchAccounts = async () => {
      try {
        const resp = await fetch(
          "/api/now/table/x_274351_finance_0_accounts?sysparm_query=active%3Dtrue%5EORDERBYnumber&sysparm_fields=sys_id%2Cnumber%2Caccount_type%2Cbalance%2Cholder&sysparm_display_value=true&sysparm_limit=100",
          {
            headers: {
              Accept: "application/json",
              "X-UserToken": getToken(),
            },
          }
        );
        if (!resp.ok) throw new Error("HTTP " + resp.status);
        const data = await resp.json();
        if (data.result && Array.isArray(data.result)) {
          setAccounts(
            data.result.map((r: any) => ({
              sys_id: r.sys_id,
              number: r.number || "",
              account_type: r.account_type || "",
              balance: r.balance || "0",
              holder: r.holder || "",
            }))
          );
        }
      } catch (e) {
        console.error("Failed to load accounts:", e);
        setAccounts([]);
      }
      setAccountsLoading(false);
    };
    fetchAccounts();
  }, []);

  const handleSubmit = async () => {
    if (!selectedAccount || !amount) {
      setMessage("Please select an account and enter an amount.");
      setMessageType("error");
      return;
    }

    setLoading(true);
    setMessage("");
    setMessageType("");
    setTransaction(null);

    try {
      const txnResp = await fetch("/api/now/table/x_274351_finance_0_txn", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",
          "X-UserToken": getToken(),
        },
        body: JSON.stringify({
          account: selectedAccount.sys_id,
          type: "ach_transfer",
          amount: amount,
          status: "completed",
        }),
      });

      if (!txnResp.ok) {
        const errBody = await txnResp.json().catch(() => ({}));
        throw new Error(
          (errBody as any)?.error?.message ||
            "Failed to create transaction (HTTP " + txnResp.status + ")"
        );
      }

      const txnData = await txnResp.json();
      const txn = txnData.result;

      setMessage("ACH transfer processed successfully!");
      setMessageType("success");
      setTransaction({
        sys_id: txn.sys_id,
        account_number: selectedAccount.number,
        amount: amount,
        type: "ach_transfer",
        status: "completed",
        webhook_status: webhookKey.trim() ? "configured" : "not_configured",
      });
    } catch (e: any) {
      setMessage(e.message || "Transfer failed. Please try again.");
      setMessageType("error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ maxWidth: "600px", margin: "24px auto", padding: "0 16px" }}>
      <h1 style={{ color: "#1a3a5c", marginBottom: "24px", fontSize: "24px" }}>
        ACH Transfer
      </h1>

      <div style={cardStyle}>
        <div
          style={{
            background: "#1a3a5c",
            color: "#fff",
            padding: "12px 16px",
            borderRadius: "8px 8px 0 0",
            fontSize: "16px",
            fontWeight: 600,
          }}
        >
          Transfer Details
        </div>
        <div style={{ padding: "16px" }}>
          <div
            style={{ display: "flex", flexDirection: "column", gap: "16px" }}
          >
            <AccountDropdown
              accounts={accounts}
              selectedAccount={selectedAccount}
              onSelect={setSelectedAccount}
              loading={accountsLoading}
            />

            <div>
              <label style={labelStyle} htmlFor="ach-amount">
                Amount *
              </label>
              <input
                id="ach-amount"
                type="number"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="0.00"
                min="0.01"
                step="0.01"
                style={inputStyle}
              />
            </div>

            <div>
              <label style={labelStyle} htmlFor="ach-description">
                Description / Notes
              </label>
              <textarea
                id="ach-description"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="Optional transfer notes"
                rows={3}
                style={{ ...inputStyle, resize: "vertical" }}
              />
            </div>

            <div>
              <label style={labelStyle} htmlFor="ach-webhook">
                Webhook Key (optional)
              </label>
              <input
                id="ach-webhook"
                type="text"
                value={webhookKey}
                onChange={(e) => setWebhookKey(e.target.value)}
                placeholder="Your webhook.site key"
                style={inputStyle}
              />
            </div>
          </div>

          <div style={{ marginTop: "20px" }}>
            <div
              role="button"
              tabIndex={0}
              onClick={loading ? undefined : handleSubmit}
              onKeyDown={(e) => {
                if (!loading && (e.key === "Enter" || e.key === " ")) {
                  e.preventDefault();
                  handleSubmit();
                }
              }}
              aria-disabled={loading}
              style={{
                display: "inline-block",
                padding: "10px 24px",
                fontSize: "14px",
                fontWeight: 600,
                color: "#fff",
                backgroundColor: loading ? "#6c757d" : "#1a3a5c",
                borderRadius: "4px",
                cursor: loading ? "not-allowed" : "pointer",
                lineHeight: "20px",
                textAlign: "center",
                userSelect: "none",
                opacity: loading ? 0.7 : 1,
              }}
              onMouseEnter={(e) => {
                if (!loading) e.currentTarget.style.backgroundColor = "#15304d";
              }}
              onMouseLeave={(e) => {
                if (!loading) e.currentTarget.style.backgroundColor = "#1a3a5c";
              }}
            >
              {loading ? "Processing..." : "Send ACH Transfer"}
            </div>
          </div>
        </div>
      </div>

      {message && (
        <div
          style={{
            ...cardStyle,
            borderLeft:
              messageType === "success"
                ? "4px solid #28a745"
                : "4px solid #dc3545",
          }}
        >
          <div style={{ padding: "16px" }}>
            <p style={{ color: "#333", margin: 0 }}>{message}</p>
          </div>
        </div>
      )}

      {transaction && (
        <div style={cardStyle}>
          <div style={{ padding: "16px" }}>
            <h2 style={{ margin: "0 0 12px 0", fontSize: "16px", color: "#1a3a5c" }}>
              Transaction Details
            </h2>
            <table style={{ width: "100%", borderCollapse: "collapse" }}>
              <tbody>
                {[
                  ["Sys ID", transaction.sys_id],
                  ["Account", transaction.account_number],
                  ["Amount", transaction.amount],
                  ["Status", transaction.status],
                  ["Webhook", String(transaction.webhook_status)],
                ].map(([label, value]) => (
                  <tr key={label} style={{ borderBottom: "1px solid #eee" }}>
                    <td
                      style={{
                        padding: "8px",
                        fontWeight: 600,
                        color: "#555",
                        width: "120px",
                      }}
                    >
                      {label}
                    </td>
                    <td style={{ padding: "8px", color: "#333" }}>{value}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}
","import React from "react";
import ReactDOM from "react-dom/client";
import App from "./app";

ReactDOM.createRoot(document.getElementById("root")!).render(<App />);
